#include<bits/stdc++.h>
using namespace std;using L=long long;int main(){for(int n=1;n<=7;n++){int N=1<<n,m=n*(n-1)/2;vector<L>d(N*n),h(N);vector<int>r(n);set<pair<L,L>> seen;for(int code=0;code<(1<<m);code++){fill(r.begin(),r.end(),0);int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,k++){if(code>>k&1)r[i]|=1<<j;else r[j]|=1<<i;}fill(d.begin(),d.end(),0);h[0]=1;for(int mask=1;mask<N;mask++){L tot=0;for(int v=0;v<n;v++)if(mask>>v&1){int sub=mask^(1<<v);L z=!sub;int pred=sub&~r[v];while(pred){int u=__builtin_ctz(pred);pred&=pred-1;z+=d[sub*n+u];}d[mask*n+v]=z;tot+=z;}h[mask]=tot;}L p=0;for(int s=0;s<N;s++)p+=h[s]*h[(N-1)^s];if(p<=512425 && seen.insert({h[N-1],p}).second){cout<<n<<' '<<h[N-1]<<' '<<p;for(int x:r)cout<<' '<<x;cout<<'\n';} }cerr<<"done "<<n<<" profiles "<<seen.size()<<endl;}}
